89	    private static SubsonicAPIClient createSubsonicApiClient(final Context context) {
90	        final SharedPreferences preferences = Util.getPreferences(context);
91	        int instance = preferences.getInt(Constants.PREFERENCES_KEY_SERVER_INSTANCE, 1);
92	        String serverUrl = preferences.getString(Constants.PREFERENCES_KEY_SERVER_URL + instance, null);
93	        String username = preferences.getString(Constants.PREFERENCES_KEY_USERNAME + instance, null);
94	        String password = preferences.getString(Constants.PREFERENCES_KEY_PASSWORD + instance, null);
95	        boolean allowSelfSignedCertificate = preferences
96	                .getBoolean(Constants.PREFERENCES_KEY_ALLOW_SELF_SIGNED_CERTIFICATE + instance, false);
97	        boolean enableLdapUserSupport = preferences
98	                .getBoolean(Constants.PREFERENCES_KEY_LDAP_SUPPORT + instance , false);
99	
100	        if (serverUrl == null ||
101	                username == null ||
102	                password == null) {
103	            Log.i("MusicServiceFactory", "Server credentials is not available");
104	            return new SubsonicAPIClient("http://localhost", "", "",
105	                    SubsonicAPIVersions.fromApiVersion(Constants.REST_PROTOCOL_VERSION),
106	                    Constants.REST_CLIENT_ID, allowSelfSignedCertificate,
107	                    enableLdapUserSupport, BuildConfig.DEBUG);
108	        }
109	
110	        return new SubsonicAPIClient(serverUrl, username, password,
111	                SubsonicAPIVersions.fromApiVersion(Constants.REST_PROTOCOL_VERSION),
112	                Constants.REST_CLIENT_ID, allowSelfSignedCertificate,
113	                enableLdapUserSupport, BuildConfig.DEBUG);
114	    }
