116	    private static PermanentFileStorage getPermanentFileStorage(final Context context) {
117	        final SharedPreferences preferences = Util.getPreferences(context);
118	        int instance = preferences.getInt(Constants.PREFERENCES_KEY_SERVER_INSTANCE, 1);
119	        final String serverId = getServerId(preferences, instance);
120	
121	        return new PermanentFileStorage(getDirectories(context), serverId, BuildConfig.DEBUG);
122	    }
