124	    public static String getServerId(final SharedPreferences sp, final int instance) {
125	        String serverUrl = sp.getString(
126	                Constants.PREFERENCES_KEY_SERVER_URL + instance, null);
127	        return String.valueOf(Math.abs((serverUrl + instance).hashCode()));
128	    }
